        "colorCode": "GRETWO/DKBLUE/CBLACK",
        "title": "TENIS MASCULINO ADIDAS RUNFALCON 6",
        "htmlDescription": "<h2>Tenis de running Runfalcon 6 CLOUDFOAM</h2>\n<p>Tenis de running versátiles con tecnología de amortiguación Cloudfoam para una comodidad constante.</p>\n<p>Lo mejor para Correr en asfalto</p>\n<p>Distancia Corta (0 - 10 Km)</p>\n<p>Tipo de pronación Neutra</p>\n<p><strong>Descripción</strong><br />Disfruta de tu día con total concentración con los tenis de running Runfalcon 6 Cloudfoam de adidas. Diseñados para ofrecer un rendimiento constante en el día a día, te acompañan en tus carreras matutinas y en las exigencias diarias con una sensación equilibrada y fiable.</p>\n<p>Su exterior de tela y sintético garantiza un ajuste ligero y transpirable. La amortiguación Cloudfoam ofrece una experiencia de comodidad integral desde el primer contacto hasta cada zancada, para un paso ultra-suave con amortiguación extra.</p>\n<p>La suela de caucho resistente al desgaste proporciona un agarre constante sobre la superficie de asfalto. Con el logo de las 3 franjas de adidas, el diseño mantiene sus raíces deportivas a la vez que conserva un aspecto limpio y versátil.</p>\n<p><strong>Detalles</strong><br />Agujetas<br />Corte: Textil / Otro Material<br />Forro: Textil<br />Suela: Otro Material<br />Mediasuela Cloudfoam<br />Peso: 282 g<br />Diferencial de la mediasuela: 10 mm (talón 36 mm / empeine 26 mm)<br />Color del artículo: Grey Two / Dark Blue / Core Black<br />Número de artículo: IH9527</p>\n<p><strong>Cloudfoam</strong><br />Comodidad en todo momento y en todo lugar<br />Una sensación de comodidad integral desde el primer paso. Para una pisada más suave y mayor amortiguación durante todo el día, todos los días.</p>\n<p> </p>",
