        "htmlDescription": "<h1 id=\"r-productname\" class=\"r-productname\">Zapatillas Caven III OG unisex</h1>\n<p><strong>HISTORIA DEL PRODUCTO</strong><br />Sentí energía PUMA con las Caven III, la fusión perfecta de un estilo retro inspirado en el básquet y una onda urbana moderna. Con detalles decorativos llamativos y una entresuela alta y texturizada, están pensadas para ofrecerte un look que se destaca. Además, vas a sentir comodidad durante todo el día, gracias a su plantilla acolchada que agrega ese toque extra.</p>\n<p><strong>CARACTERÍSTICAS Y BENEFICIOS</strong><br />SOFTFOAM+: Plantilla cómoda, diseñada con un talón extra grueso para proporcionar una amortiguación suave<br />Capellada fabricada con al menos un 30% de materiales reciclados; base fabricada con al menos un 10% de materiales reciclados</p>\n<p><strong>DETALLES</strong><br />Calce regular<br />Puntera redondeada<br />Con cordones<br />Talón plano<br />Detalles de la marca PUMA</p>\n<p><strong>Composición y materiales</strong><br />Exterior: 46.5% Sintético, 46.5% Sintético, 2.11% Textil, 2.11% Textil, 51.39% Piel reconstituida, 51.39% Piel reconstituida<br />Plantilla: 100% Textil, 100% Textil<br />Forro: 100% Textil, 100% Textil<br />Suela: 100% Goma, 100% Goma</p>",
