        "htmlDescription": "<h1>1906R</h1>\n<p><strong>Descripción</strong></p>\n<p>El modelo 1906R, al igual que sus primos 2002R y 860v2, se compone de una suela que incluye una combinación de amortiguación ACTEVA LITE flexible, absorción de impactos N-ergy y cápsulas segmentadas ABZORB SBS en el talón. El enfoque de alta tecnología también se refleja en el diseño superior del 1906R, que incluye una malla con orificios abiertos y una serie de superposiciones sintéticas curvilíneas. Esta versión distintiva de las convenciones de diseño de la época ofrece un refinamiento del legado de alto rendimiento.</p>\n<p><strong>Detalles del producto</strong><br /><strong>Características</strong><br />Amortiguación ACTEVA LITE en la entresuela<br />Amortiguación ABZORB SBS en el talón<br />La suela N-ergy absorbe mejor los impactos<br />La tecnología Stability Web en la suela proporciona mayor soporte en el arco<br />Caja de TPU en el talón<br />Suela de goma<br /> 411 grams (14.5 oz)</p>\n<p><strong>Material</strong><br />Parte superior de malla con superposiciones sintéticas<br />Empeine de malla<br />Estilo #: M1906</p>\n<p><strong>Talla y ajuste</strong><br />Se ajusta a lo esperado para la mayoría de la gente </p>\n<p>Este calzado es ideal para: <br />Pies con ancho medio</p>\n<p>Altura del arco media</p>\n<p>Altura del pie media</p>\n<p>Tallones anchos</p>\n<p>Cierre con cordones ajustables que proporcionan un ajuste firme</p>",
