        "title": "TENIS FEMENINO PUMA ST MILER RISE",
        "htmlDescription": "<h2>Zapatillas St Miler unisex</h2>\n<p><strong>descripción</strong><br />Las zapatillas PUMA St Miler son para quienes caminan con intención y estilo. Estas zapatillas presentan un diseño refinado que combina un atractivo atemporal con un toque moderno. Tanto si te mueves por las calles de la ciudad como si quedas para pasar un relajado fin de semana, las St Miller te ofrecen una comodidad inigualable y una frescura sencilla. Atrevidas pero refinadas, estas zapatillas son para quienes saben que el verdadero estilo se basa en los detalles. Entra en algo clásico, entra en las St Miler.</p>\n<p>Modelo: 402665</p>\n<p><strong>características + beneficios</strong><br />SOFTFOAM+: cómoda plantilla diseñada para proporcionar una suave amortiguación gracias a su talón extragrueso</p>\n<p><strong>detalles</strong><br />Ancho: estándar<br />Tipo de puntera: redondeada<br />Cierre: de cordones<br />Tipo de talón: plano<br />Forro: textil<br />Suela: goma</p>\n<p><strong>materiales y cuidado</strong><br />Información de material<br />Entresuela: 100% Sintético<br />Plantilla: 100% Textil<br />Suela: 100% Goma<br />Exterior: 37.91% Piel de vacuno, 32.60% Textil, 29.49% Sintético<br />Forro: 100% Textil</p>",
