        "htmlDescription": "<h1>Zapatos Lowell Moc Toe de piel</h1>\n<p>Zapatos Lowell Moc Toe de piel<br />El zapato Lowell de 4 ojales combina la estética contemporánea con un diseño de ropa de trabajo de archivo. Está confeccionado en piel Orleans con un cómodo cuello acolchado, costuras y una puntera de estilo mocasín. La acanalada suela BEN está marcada con el emblemático pespunte amarillo.</p>\n<p><br />Orleans es una piel encerada ligeramente texturizada, flexible, resistente y con un sutil efecto que cambia ligeramente de color al doblarla o al aplicarle presión. Limpiar con un paño húmedo y cuidar con el Dr. Martens Shoe Polish.<br />Diseñada en los años 80, la suela BEN presenta tacos profundos y un robusto patrón<br />Todos nuestros modelos con empalmillado Goodyear se han sellado a 700 ºC y están reforzados con nuestro emblemático pespunte<br />Product code: 31817243</p>\n<p><strong>Orleans</strong><br />Orleans es una piel encerada ligeramente texturizada y flexible, con un sutil efecto que cambia ligeramente de color al doblarla o al aplicarle presión.</p>\n<p><strong>Cuidado del material</strong><br />Limpia la suciedad con un paño húmedo y deja secar. A continuación, aplica un betún neutro o de color de Dr. Martens, según el material. Frota la piel con el cepillo de cerdas para zapatos de Dr. Martens para recuperar el brillo.</p>\n<p> </p>",
