        "htmlDescription": "<p> </p>\r\n<h2>Zebzag Suede Slingback Platform Mules</h2>\r\n<p><strong>Detalles</strong><br />Las mules Zebzag son nuestra última innovación en comodidad: construidas sobre una suela híbrida con amortiguación de aire que fusiona EVA ultraligera con PVC resistente. Elaboradas en gamuza ligera y versátil, están diseñadas para usarse como quieras, en verano o fuera de la temporada convencional. La correa ajustable garantiza un ajuste seguro, mientras que la construcción con ribete proporciona nuestra durabilidad característica. Las costuras amarillas en el ribete identifican a estas mules como Dr. Martens.</p>\r\n<p><strong>Construcción:</strong></p>\r\n<p>Fabricadas con líneas cosidas con la técnica Goodyear, termoselladas y reforzadas con nuestra costura distintiva.<br />Altura de la suela: Plataforma: 2,5 cm; Altura del tacón: 3,2 cm.<br />Plantilla: Más ancha y con puntera redondeada.<br />Material: Gamuza E.H.: una piel clásica con una textura sedosa al tacto.</p>\r\n<p><strong>Instrucciones de cuidado:</strong></p>\r\n<p>Limpiar con un cepillo para gamuza o de cerdas duras.</p>\r\n<p><strong>Construcción</strong><br />Construcción Goodyear Welted: la parte superior y la suela están termoselladas y cosidas juntas, lo que proporciona mayor comodidad y durabilidad durante años.</p>\r\n<p><strong>Código de producto</strong><br />31737439</p>",
