        "title": "ZAPATOS UNISEX DR. MARTENS 2976 YELLOW STITCH",
        "htmlDescription": "<h1>Botas Chelsea 2976 YS de piel Crazy Horse</h1>\n<p>Silueta clásica.<br />Piel resistente.<br />Suela emblemática.<br />Un clásico subversivo. La bota Chelsea 2976 YS se desvía del camino marcado con todos los distintivos de DM's.</p>\n<p>El emblemático pespunte amarillo. Borde acanalado. Paneles elásticos. La suela DMS original está termosellada, presenta el característico borde acanalado y cuenta con cámara de aire para aportar rebote a cada paso. Crazy Horse es una piel texturizada y resistente, con variaciones naturales de color que se hacen visibles al rozarla o arañarla.</p>\n<p>Product code: 27486600</p>\n<p>PIEL CRAZY HORSE</p>\n<p><strong>Composition</strong></p>\n<p>Piel de vacuno</p>\n<p>Resistente y con acabado aceitado. Crazy Horse es una piel con carácter, de gran grosor y con una profundidad de color auténtica</p>\n<p><br />Piel de vacuno de plena flor corregida y pulida, tratada con capas de aceite y cera que provocan variaciones naturales de color cuando se raya o se frota. Con muchísima personalidad, tiene un aspecto envejecido y gastado desde el primer momento.</p>\n<p> </p>\n<p>Desarrollada en Prime Tanning, una curtiduría de EE. UU. a mediados de los 80, e inspirada en las pieles tradicionales de guarnicionería, la Crazy Horse se remata con aceites y ceras para lograr un sutil efecto que hace que cambie ligeramente de color al doblarla o al aplicarle presión. Con el tiempo, los aceites naturales tienden a subir a la superficie de la piel, creando un aspecto brumoso llamado «bloom»</p>\n<p><br />A veces llamada piel de silla de montar, la Crazy Horse suele dejar a la vista cada rozadura o arañazo. Pero también responde especialmente bien al Wonder Balsam si quieres encerar y borrar esas marcas.</p>\n<p><strong>GUÍAS DE CUIDADO</strong></p>\n<p>Cuidado del material<br />Limpia la suciedad con un paño húmedo y deja secar la piel, luego aplica el bálsamo Wonder Balsam de Dr. Martens con la esponja proporcionada con el producto.</p>",
        "brand": "DR. MARTENS",
        "productType": "CALZADO",
        "family": "ZAPATOS",
