        "referenceCode": "20DRM26230001",
        "colorCode": "BLACK SMOOTH",
        "title": "ZAPATOS UNISEX DR. MARTENS 101 YS",
        "htmlDescription": "<h1>Botines 101 Yellow Stitch de piel Smooth</h1>\n<p>Botines 101 Yellow Stitch de piel Smooth<br />Una actualización del distintivo rojo cereza que ha sido parte del ADN 101 de 6 ojales desde el principio. Fabricado con nuestro cuero liso, clásico y duradero. Se fija a una suela resistente con colchón de aire, nuestros distintivos pespuntes amarillos reforzados en vira de Goodyear y termina con una tira en forma de bucle en el talón. Tomando inspiración del pasado y dando un paso hacia adelante.</p>\n<p><br />Originalmente creada para trabajadores pero subvertida por rebeldes. La bota 101 lleva todo el ADN dentro de una silueta de 6 ojale<br />Nuestro cuero Smooth es famoso por ser resistente y duradero. Lo puedes pulir para obtener más brillo, o dejar que tome sus características naturales con el uso<br />Selladas con nuestra vira Goodyear al calor de 700°C y reforzadas con nuestro distintivo pespunte<br />Una horma estándar -recomendada para pies normales a anchos<br />Product code: 26230001</p>\n<p><strong>PIEL SMOOTH</strong></p>\n<p><strong>Composition</strong></p>\n<p>Piel de vacuno</p>\n<p>Nuestra sello. Resistente, fuerte y hecha para durar.</p>\n<p>Una piel de grano corregido, lijada y pulida con un proceso de residuos reducidos para un acabado uniforme</p>\n<p> </p>\n<p>Una piel de grano corregido que se lija y se pule, y luego se recubre con pigmento para un acabado uniforme y un color consistente que nos permite conseguir, junto a otros tonos, el negro más auténtico.</p>\n<p>El curtido y el acabado hacen que tus zapatos o botas puedan sentirse rígidos al principio. Pero con un uso y un cuidado adecuado, incluido masajearlos con Wonder Balsam, la piel irá cediendo poco a poco y se adaptará a tus pies.</p>\n<p><strong>Cuidado del material</strong><br />Limpia la suciedad con un paño húmedo y deja secar. A continuación, aplica un betún neutro o de color de Dr. Martens, según el material. Frota la piel con el cepillo de cerdas para zapatos de Dr. Martens para recuperar el brillo.</p>",
        "brand": "DR. MARTENS",
        "productType": "CALZADO",
        "family": "ZAPATOS",
