        "htmlDescription": "<h2>Cortavientos R-Trail Nature Mujer</h2>\r\n<p><strong>Descripción</strong><br />Cortavientos de trail running para mujer. Diseñado para enfrentarse a las condiciones más exigentes en montaña y senderos. Alta gama que ofrece una impermeabilidad de 10.000 mm y transpirabilidad 10K, manteniendo a la corredora seca por fuera y cómoda por dentro. Ligero y con ajuste ergonómico, es ideal para actividades intensas al aire libre bajo la lluvia.</p>\r\n<p>Incorpora cierre con cremallera waterproof. La capucha cuenta con visera, ajuste elástico y excelente sujeción para evitar deslizamientos. En los puños y la cintura incluye banda elástica para mayor adaptabilidad.</p>\r\n<p>Costuras termoselladas y waterproof.</p>\r\n<p>La parte trasera y los costados cuentan con un sistema de ventilación del sudor.</p>\r\n<p>Presenta un diseño ergonómico y autoguardable en su propio bolsillo.</p>\r\n<p>Está elaborado con tejido ultraligero, ultrarresistente (ripstop) e impermeable, que repele el agua. Nivel de impermeabilidad de alta gama (10.000 mm), resistente a lluvia prolongada, fuerte y aguanieve, y reforzado con costuras waterproof. También es transpirable 10K. Es decir, esta prenda permite evacuar 10.000 gramos de humedad por metro cuadrado en 24 horas.</p>\r\n<p>Los detalles reflectantes de seguridad aumentan la visibilidad del trail runner en situaciones de poca luminosidad.</p>\r\n<p><strong>Características</strong><br />Cierre de cremallera con tirador y protector de barbilla<br />Manga tipo raglán<br />Bajo y puños elásticos<br />Capucha autoguardable con visera<br />Bolsillo interior<br />Plegable<br />Tejido elástico, transpirable y resistente al agua<br />Incluye sistema de ventilación en las zonas de mayor sudoración<br />Impermeable<br />Dimensiones bolsillo autoguardable: 10 cm x 12 cm x {2} cm<br />Tipo de ajuste: estándar<br />100% Nylon</p>\r\n<p><strong>Alta calidad</strong></p>\r\n<p>Preda que, por su composición y/o características técnicas, ofrece altos estándares de calidad. Incorpora tejido técnico y tecnología de vanguardia para ayudar al deportista a alcanzar el máximo rendimiento.</p>\r\n<p><strong>Diseño compacto</strong></p>\r\n<p>Prenda con diseño compacto que, gracias a su bajo volumen y ligereza, se dobla y se pliega fácilmente para guardarla ocupando el menor espacio posible. Puede transportarse con comodidad.</p>\r\n<p><strong>Durabilidad</strong></p>\r\n<p>Prenda que evita el deterioro rápido de la fibra y de los colores. Su elevada durabilidad y su resistencia al desgaste y las roturas aumenta la vida útil del producto.</p>\r\n<p><strong>Libertad de movimientos</strong></p>\r\n<p>Prenda que, por su construcción, por su elaboración en punto elástico y/o por sus características técnicas facilitan el movimiento a la hora de practicar deporte. Gracias a esta adaptación, el cuerpo se mueve con total libertad.</p>\r\n<p><strong>Transpirable</strong></p>\r\n<p>Tejido que ofrece una correcta transpiración del sudor. Gracias a su composición o a la incorporación de sistemas como MICRO-MESH SYSTEM o perforaciones, ayuda a expulsar la humedad y a mantener el cuerpo seco durante la práctica deportiva.</p>\r\n<p><strong>Bolsillo invisible</strong></p>\r\n<p>Tecnología que consiste en la incorporación bolsillos en zonas estratégicas de forma que no se aprecian a simple vista y que no rompen la estética del producto. Permiten guardar objetos específicos de primera necesidad.</p>\r\n<p><strong>Impermeable (10K)</strong></p>\r\n<p>Tecnología que protege contra la lluvia. Columna de agua de 10.000 mm testada en el laboratorio de desarrollo de Joma. Máxima resistencia contra lluvias y nevadas fuertes durante períodos de tiempo prolongados.</p>\r\n<p><strong>Secado rápido</strong></p>\r\n<p>Gracias al tejido ligero que incorpora, la prenda se seca con mayor rapidez. Facilita el uso de la prenda con una mayor rapidez.</p>\r\n<p><strong>Cuidados</strong><br />Lavar a máquina sin superar 30 grados<br />No utilizar lejía<br />No secar a máquina<br />Planchar a temperatura máxima de 110 grados</p>\r\n<p> </p>",
        "brand": "JOMA",
        "productType": "ROPA",
        "family": "ABRIGOS",
