        "title": "ZAPATOS MASCULINO TIMBERLAND AF 6IN PREMIUM WATERPROOF",
        "htmlDescription": "<p><!-- x-tinymce/html --></p>\r\n<h2><!-- x-tinymce/html --></h2>\r\n<h2>Men’s Timberland® Premium 6-Inch Waterproof Boot</h2>\r\n<p><strong>Descripción:</strong><br />Inspiradas en nuestra bota impermeable original, estas botas para todas las estaciones ofrecen un rendimiento impermeable incansable y el inconfundible estilo de bota de trabajo. Otras características esenciales incluyen 400 gramos de aislamiento PrimaLoft® cálido y sin plumón, un cuello acolchado para un ajuste cómodo alrededor del tobillo y una suela de goma con tacos para una mayor tracción. Están fabricadas con materiales de calidad, como el forro de tela ReBOTL™, que contiene al menos un 50 % de plástico reciclado. Timberland apoya la fabricación responsable de cuero a través del Leather Working Group.</p>\r\n<p><strong>Características</strong>:<br /><br /><strong>Timberland® Impermeable</strong><br />Nuestro calzado impermeable incorpora una variedad de materiales, tratamientos y procesos de impermeabilización avanzados. Comenzamos con cueros impermeables que se sellan durante el proceso de curtido; luego, sellamos las costuras del calzado o utilizamos una membrana interna impermeable y transpirable para mantener los pies secos. Las lengüetas y cremalleras, tratadas con revestimientos resistentes al agua de larga duración, incorporan fuelles integrados para evitar aún más la entrada de agua.</p>\r\n<p><strong>Material ReBOTL™</strong><br />Miles de millones de botellas en todo el mundo se recolectan, reciclan y transforman en hilos de RPET que luego utilizamos para fabricar productos, lo que ayuda a reducir los residuos y a generar empleo. Las prendas con material ReBOTL™ contienen al menos un 40 % de plástico reciclado.<br />Cuero de calidad<br />Cuero de calidad<br />Cuero respetuoso con el medio ambiente procedente de curtidurías con calificación plata u oro del Leather Working Group por sus prácticas de gestión de agua, energía y residuos.</p>",
        "brand": "TIMBERLAND",
        "productType": "CALZADO",
        "family": "ZAPATOS",
        "subFamily": "BOTA",
