        "colorCode": "BLACK",
        "title": "SANDALIAS UNISEX BIRKENSTOCK ARIZONA BF",
        "htmlDescription": "<p>Arizona<br />Birko-Flor</p>\r\n<p></p>\r\n<p>Un &iacute;cono de dise&ntilde;o atemporal y comodidad legendaria, la sandalia Arizona ha definido el estilo desde 1973. El estilo relajado viene en Birko-Flor&reg; duradero para un acabado cl&aacute;sico similar al cuero. Completo con elementos de dise&ntilde;o legendarios de BIRKENSTOCK, como una plantilla de corcho y l&aacute;tex contorneada para brindar lo &uacute;ltimo en soporte.<br />La plantilla contorneada de corcho y l&aacute;tex crea un soporte personalizado con el desgaste<br />Empeine de cuero sint&eacute;tico Birko-Flor&reg;<br />El forro de la plantilla de gamuza te ayuda a mantenerte c&oacute;modo<br />La suela de EVA es flexible y ligera.<br />Dos correas ajustables con hebillas de metal<br />Sello de calidad \"Made in Germany\" en la plantilla</p>\r\n<p>Material superior: Birko-Flor&reg;<br />Birko-Flor&reg; es un material sint&eacute;tico respetuoso con la piel, resistente al desgarro y f&aacute;cil de cuidar que BIRKENSTOCK utiliza exclusivamente.</p>\r\n<p>Plantilla: Piel natural<br />El cuero natural se puede reconocer por su superficie sin tratar. BIRKENSTOCK deliberadamente no trata los granos superficiales y otras caracter&iacute;sticas. BIRKENSTOCK utiliza cuero resistente con un grosor de 2,8 a 3,2 mil&iacute;metros como material superior.</p>\r\n<p>Material de la plantilla: Corcho<br />El corcho es un material sostenible extra&iacute;do de la capa de corteza del alcornoque. Este producto natural es aislante y ofrece una muy buena amortiguaci&oacute;n.</p>\r\n<p>Suela: EVA<br />El EVA (etilenvinilacetato) es un material el&aacute;stico de alta calidad, muy ligero y con una excelente amortiguaci&oacute;n. Como resultado, alisa las peque&ntilde;as irregularidades del suelo y asegura que cada paso quede suavemente amortiguado.</p>\r\n\r\n<iframe width=\"848\" height=\"659\" src=\"https://www.youtube.com/embed/UaGZUwhd5ZU\" title=\"Arizona Birko-Flor Black\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture\" allowfullscreen></iframe>",
        "brand": "BIRKENSTOCK",
        "productType": "CALZADO",
