        "htmlDescription": "<p><strong>Speedcat OG Sneakers Unisex</strong></p>\r\n<p><strong>HISTORIA DEL PRODUCTO</strong><br />Las PUMA Speedcat han sido un &iacute;cono de la cultura de las carreras y el estilo urbano durante d&eacute;cadas. El mundo las conoci&oacute; inicialmente como unas zapatillas ultrafinas dise&ntilde;adas para reducir los tiempos de vuelta en milisegundos. Posteriormente, se convirtieron en un elegante b&aacute;sico de la moda urbana, presente en las calles de las capitales mundiales de la moda. Su historia evoluciona constantemente, ya que son adoptadas por los creadores de tendencias y los pioneros de cada generaci&oacute;n. Reescribe los cl&aacute;sicos con las Speedcat.</p>\r\n<p><strong>CARACTER&Iacute;STICAS Y BENEFICIOS</strong><br />IMEVA: El material de PUMA para una sensaci&oacute;n ligera y c&oacute;moda<br />Los productos de cuero de PUMA apoyan la fabricaci&oacute;n responsable a trav&eacute;s del Leather Working Group. www.leatherworkinggroup.com<br /><strong>DETALLES</strong><br />Ajuste regular<br />Puntera redondeada<br />Parte superior de cuero<br />Cierre de cordones<br />Suela de goma<br />Franja caracter&iacute;stica de PUMA de ante en el lateral<br />PUMA Cat bordado en la puntera</p>",
